<script nonce="<?= htmlspecialchars(\App\Core\Security::nonce(),ENT_QUOTES,'UTF-8') ?>">(()=>{const list=document.getElementById('block-list'),order=document.getElementById('block-order');if(!list||!order)return;const sync=()=>order.value=[...list.children].map(x=>x.dataset.block).join(',');list.addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(!b)return;const row=b.closest('.layout-block');if(b.dataset.move==='up'&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);if(b.dataset.move==='down'&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);sync()});sync()})();</script>
